const MODES = [
  ['alias','Alias','team'], ['charades','Charades','team'], ['taboo','Taboo','team'],
  ['cards','Flashcards','solo'], ['quiz','Quick Quiz','solo'], ['match','Match','solo'], ['spell','Spell It','solo'], ['blocks','Blocks','solo'], ['list','Word list','solo']
];
const $ = s => document.querySelector(s);
const shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
function save(k, v){ try{ localStorage.setItem('ifarenaTB2:'+k, JSON.stringify(v)); }catch(e){} }
function load(k, d){ try{ const v = localStorage.getItem('ifarenaTB2:'+k); return v ? JSON.parse(v) : d; }catch(e){ return d; } }
const hashLesson = (location.hash || '').replace('#','').toUpperCase();
let lesson = DATA[hashLesson] ? hashLesson : load('lesson', Object.keys(DATA)[0]);
if (!DATA[lesson]) lesson = Object.keys(DATA)[0];
let mode = load('mode', 'alias');
if (!MODES.some(m => m[0] === mode)) mode = 'alias';
